mapper.select:
/* PushTargetMapper.selectTbmEnteredTargets */
SELECT DISTINCT
       AT.CMPNY_CD    AS cmpnyCd
     , AT.USER_CD     AS userCd
  FROM TB_TBM_ATTENDANCE AT
 WHERE AT.SESSION_CD = #{sessionCd}
   AND AT.DEL_YN     = 'N'
   AND AT.ENTRY_AT IS NOT NULL
   AND NULLIF(TRIM(AT.USER_CD), '') IS NOT NULL
   AND EXISTS (
         SELECT 1
         FROM TB_TBM_SESSION S
         WHERE S.SESSION_CD = #{sessionCd}
           AND S.CMPNY_CD = #{hostCmpnyCd}
       )
